const order = $json;

const flags = [];
let riskLevel = 'low';
let needsApproval = false;

// --- Payment status ---
const financial = (order.financial_status || 'unknown').toLowerCase();
let paymentState = 'unknown';
if (financial === 'paid') paymentState = 'paid';
else if (['pending', 'authorized', 'partially_paid'].includes(financial)) paymentState = 'pending';
else if (['voided', 'refunded', 'declined'].includes(financial)) paymentState = 'failed';

if (paymentState === 'pending') flags.push('Pending payment');
if (paymentState === 'failed') { flags.push('Failed/voided payment'); riskLevel = 'high'; }

// --- Product / variant availability ---
const lineItems = Array.isArray(order.line_items) ? order.line_items : [];
const outOfStock = lineItems.filter(li => Number(li.fulfillable_quantity) < Number(li.quantity));
if (outOfStock.length > 0) {
  flags.push('Out-of-stock / insufficient inventory: ' + outOfStock.map(li => (li.sku || li.title)).join(', '));
  if (riskLevel === 'low') riskLevel = 'medium';
}

// --- Shipping information completeness ---
const ship = order.shipping_address || {};
const requiredShip = ['address1', 'city', 'zip', 'country'];
const missingShip = requiredShip.filter(f => !ship[f]);
const shippingComplete = missingShip.length === 0;
if (!shippingComplete) {
  flags.push('Missing shipping info: ' + missingShip.join(', '));
  if (riskLevel === 'low') riskLevel = 'medium';
}

// --- Duplicate / suspicious heuristics ---
// (Deeper duplicate detection against a store of processed IDs comes in a later phase.)
const total = parseFloat(order.total_price || '0');
if (total >= 500) { flags.push('High-value order (manual review recommended)'); riskLevel = 'high'; }
if (order.customer && Number(order.customer.orders_count) === 0 && total >= 200) {
  flags.push('First-time customer, high value (possible fraud)');
  riskLevel = 'high';
}

// --- Assign order status ---
let orderStatus;
if (paymentState === 'failed') orderStatus = 'Payment failed - hold';
else if (paymentState === 'pending') orderStatus = 'Awaiting payment';
else if (outOfStock.length > 0) orderStatus = 'Paid - inventory issue';
else if (!shippingComplete) orderStatus = 'Paid - shipping info needed';
else orderStatus = 'Paid - ready for fulfillment';

// --- Recommended action + approval gate ---
let recommendedAction;
if (riskLevel === 'high') {
  needsApproval = true;
  recommendedAction = 'Hold order and request human approval before any irreversible action.';
} else if (orderStatus === 'Paid - ready for fulfillment') {
  recommendedAction = 'Proceed to fulfillment workflow.';
} else {
  recommendedAction = 'Resolve the flagged issue(s) before fulfillment.';
}

const customerName = order.customer
  ? [order.customer.first_name, order.customer.last_name].filter(Boolean).join(' ')
  : (ship.name || 'Unknown');

const lineItemsSummary = lineItems
  .map(li => `${li.quantity} x ${li.title}${li.variant_title ? ' (' + li.variant_title + ')' : ''} [${li.sku || 'no-sku'}]`)
  .join('; ');

return [{
  json: {
    order_id: String(order.id),
    order_number: order.name || ('#' + order.order_number),
    created_at: order.created_at,
    customer_name: customerName,
    customer_email: order.email || (order.customer && order.customer.email) || '',
    total_price: order.total_price,
    currency: order.currency,
    payment_state: paymentState,
    order_status: orderStatus,
    line_items_summary: lineItemsSummary,
    shipping_complete: shippingComplete,
    flags: flags.length ? flags.join(' | ') : 'None',
    risk_level: riskLevel,
    needs_approval: needsApproval,
    recommended_action: recommendedAction,
    processed_at: $now.toISO(),
    execution_id: $execution.id,
  }
}];

